"""Extract the real logger and buffer shadow lifecycle; adapt only OS I/O and dependencies."""
import argparse
import hashlib
import json
import re
from pathlib import Path


def block(text, marker):
    if text.count(marker) != 1:
        raise ValueError(f"Expected one production marker: {marker}")
    start = text.index(marker)
    opening = text.index("{", start)
    tokens = re.compile(r'"(?:\\.|[^"\\])*"|\'(?:\\.|[^\'\\])*\'|//[^\n]*|/\*.*?\*/|[{}]', re.S)
    depth = 0
    for match in tokens.finditer(text, opening):
        if match[0] == "{":
            depth += 1
        elif match[0] == "}":
            depth -= 1
            if depth == 0:
                return text[start:match.end()]
    raise ValueError(f"Unclosed production block: {marker}")


def prepare(source, output, negative_control=None):
    util = source / "bridge/src/util/log"
    header = (util / "log.h").read_text(encoding="utf-8")
    implementation = (util / "log.cpp").read_text(encoding="utf-8")
    buffer = (source / "bridge/src/client/lockable_buffer.h").read_text(encoding="utf-8")
    notices = header[:header.index("#pragma once")]
    declaration = block(header, "class Logger {")
    gate = "return !logger || level >= logger->m_level;"
    if declaration.count(gate) != 1:
        raise ValueError("Expected the production lazy gate, including pre-init buffering")
    if negative_control == "preinit-drop":
        declaration = declaration.replace(gate, "return logger && level >= logger->m_level;")
    logger = notices + "#pragma once\nnamespace bridge_util {\n"
    logger += block(header, "enum class LogLevel:") + ";\n" + declaration + ";\n"
    logger += block(header, "template<typename... Args>") + "\n"
    logger += "}\nstruct GlobalOptions { static bridge_util::LogLevel getLogLevel() { return initialLevel; }\n"
    logger += "inline static bridge_util::LogLevel initialLevel = bridge_util::LogLevel::Trace; };\n"
    logger += "namespace bridge_util {\n"
    for line in ["Logger* Logger::logger = nullptr;", "Logger::PreInitMessageArr Logger::s_preInitMsgs;", "std::mutex Logger::s_mutex;"]:
        if implementation.count(line) != 1:
            raise ValueError(f"Expected static logger state: {line}")
        logger += line + "\n"
    for marker in ["void Logger::init()", "Logger& Logger::get()", "Logger::Logger(", "Logger::~Logger()",
                   "void Logger::emitPreInitMsgs()", "void Logger::trace(", "void Logger::debug(",
                   "void Logger::emitMsg(", "void Logger::emitLine(", "std::stringstream Logger::formatMessage(",
                   "void Logger::set_loglevel("]:
        logger += block(implementation, marker) + "\n"
    logger += "}\n"
    lifecycle = block(buffer, "void initShadowMem()") + "\n" + block(buffer, "~LockableBuffer()")
    if lifecycle.count("Logger::traceLazy([&]() { return format_string(") != 2:
        raise ValueError("Expected exactly two production shadow trace producers")
    if negative_control == "eager-buffer":
        lifecycle = lifecycle.replace("Logger::traceLazy([&]() { return format_string(", "Logger::trace(format_string(")
        if lifecycle.count("g_totalBufferShadow); });") != 2:
            raise ValueError("Cannot restore eager shadow logging control")
        lifecycle = lifecycle.replace("g_totalBufferShadow); });", "g_totalBufferShadow));")
    fixture = notices + "#pragma once\ntemplate<bool bIsVertexBuffer> struct LockableBuffer {\n"
    fixture += "struct Descriptor { unsigned Size; unsigned Usage = 0; };\nDescriptor m_desc;\n"
    fixture += "bool m_bUseSharedHeap = false;\nSharedHeap::AllocId m_bufferId = SharedHeap::kInvalidId;\n"
    fixture += "l4d2_buffer::Storage m_shadow;\nstd::unique_ptr<l4d2_buffer::MappedBufferShadow> m_mappedShadow;\n"
    fixture += "bool hasShadow() const { return m_shadow || m_mappedShadow; }\ninline static size_t g_totalBufferShadow = 0;\n"
    fixture += "l4d2_data::Resource m_dataTrace;\nstd::vector<unsigned> m_lockInfos;\n"
    fixture += "explicit LockableBuffer(unsigned size) : m_desc{size} { initShadowMem(); }\n" + lifecycle + "\n};\n"
    output.mkdir(parents=True, exist_ok=True)
    outputs = {"lazy_logging_production.h": logger, "lazy_logging_buffer.h": fixture}
    for name, text in outputs.items():
        (output / name).write_text(text, encoding="utf-8", newline="\n")
    metadata = {
        "variant": negative_control or "current",
        "source_sha256": {name: hashlib.sha256(text.encode()).hexdigest() for name, text in
                          {"log.h": header, "log.cpp": implementation, "lockable_buffer.h": buffer}.items()},
        "extracted_sha256": {name: hashlib.sha256(text.encode()).hexdigest() for name, text in outputs.items()},
        "boundary": "Real Logger class, levels, lazy helpers, construction, buffering, filtering, formatting, emission and level changes; real buffer init/destructor bodies. Clock/file APIs, configuration and buffer allocator are deterministic test adapters. No graphics work or FPS claim.",
    }
    (output / "extraction.json").write_text(json.dumps(metadata, indent=2) + "\n", encoding="utf-8")


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("source", type=Path)
    parser.add_argument("output", type=Path)
    parser.add_argument("--negative-control", choices=["eager-buffer", "preinit-drop"])
    args = parser.parse_args()
    prepare(args.source, args.output, args.negative_control)
